      "Σήμερα σώζεται το δωμάτιο του συγγραφέα και κάποια προσωπικά αντικείμενα ενώ στο εστιατόριο του ξενοδοχείου Plaza de Armas ακόμη σερβίρουν το αγαπημένο του πιάτο. Ανεβαίνοντας στην ταράτσα με το ασανσέρ ο επισκέπτης έχει θέα στην είσοδο του λιμανιού της Αβάνας. Η κεντρική του τοποθεσία το καθιστά ένα εξαιρετικό ξενοδοχείο στο ιστορικό κέντρο της Αβάνας.",
