      "introEl": "Σε προνομιακό σημείο του ιστορικού κέντρου της Αβάνας αναγεννιέται ένα μεγαλοπρεπές νεοκλασικό μέγαρο, η πρωην οικία του Don José Ricardo O´Farrill, δισέγγονος του Ιρλανδού Don Ricardo O´Farrill y O´Daly, που ανήκε σε μία από τις πιο εύρωστες και αριστοκρατικές οικογένειες την εποχή της Ισπανικής αποικιοκρατίας.\r\n\r\nΤα 38 δωμάτιά του, το εστιατόριο και το σνακ μπαρ, το εσωτερικό πάτιο με το νοσταλγική του στέρνα και τη ταράτσα με την επιβλητική θέα, καθιστούν το ξενοδοχείο ένα μέρος απαράμιλλης αρχιτεκτονικής. Ο συνδυασμός αρχιτεκτονικών στοιχείων από τον 18ο, 19ο και 20ο αιώνα και η ξεχωριστή διακόσμηση των τριων επιπέδων, δημιουργούν στους επισκέπτες ένα ξεχωριστό συναίσθημα παράδοσης και εκσυγχρονισμού. Ζήστε αυτή τη μοναδική εμπειρία!",
