      "introEn": "The hotel 5* Paradisus Los Cayos της αλυσίδας Melia βρίσκεται σε ένα πανέμορφο φυσικό περιβάλλον στο βόρειο αρχιπέλαγος της Κούβας στο εξωτικό νησί Cayo Santa Maria. Πρόκειται για ένα σύγχρονο πολυτελές μοντέρνο κτήριο, το οποίο εγκαινιάστηκε στις 15 Δεκεμβρίου του 2018. Η εξαίσια αρχιτεκτονική του Paradisus Los Cayos, που αποτελείται από τρία bungalows με ευρύχωρες σουίτες και Junior σουίτες, συνδυάζεται αρμονικά με τον περιβάλλοντα χώρο.\r\nΣτο μοναδικό Paradisus Los Cayos θα απολαύσετε αποκλειστικές “βασιλικές υπηρεσίες” (Royal Service) με προσωπικό butler, θα έχετε τη δυνατότητα να χαλαρώσετε στην πισίνα, να δοκιμάσετε εξατομικευμένα προγράμματα στο γυμναστήριο, κουβανέζικο μασάζ και πολλές ακόμη υπηρεσίες.\r\nThe hotel Paradisus Los Cayos αποτελεί ιδανικό προορισμό διακοπών για ζευγάρια, παρέες, επαγγελματικά ταξίδια αλλά και οικογενειακά ταξίδια.\r\nΠαροχές ξενοδοχείου: Ιατρικές υπηρεσίες όλο το 24ωρο, γραφείο πληροφοριών και υπηρεσίες πληροφοριών όλο το 24ωρο, γυμναστήριο με ομαδικά και ατομικά προγράμματα εκγύμνασης, υπηρεσίες συναλλαγών, ειδικός διαμορφωμένος χώρος για παιδιά (Kid’s Club), SPA, μασάζ, κομμωτήριο, 34 πισίνες, πληθώρα από αθλητικές δραστηριότητες, μαθήματα ισπανικών, αίθουσες συνεδριάσεων, εστιατόρια, δωρεάν Wi Fi.\r\nΠαροχές δωματίων: υπηρεσία δωματίου, κλιματισμός, ηλεκτρική καφετιέρα (παρέχεται καφές καθημερινά), τηλεόραση με επίπεδη οθόνη, προσωπικό μπάνιο με μπανιέρα και ντους, χώρος συναντήσεων, τηλέφωνο, χρηματοκιβώτιο, στεγνωτήρας μαλλιών, μεγάλος καθρέπτης, μπουρνούζι και παντόφλες, σίδερο, mini bar, ομπρέλες, μενού επιλογής μαξιλαριών, Wi-Fi.\r\nΕστιατόρια/μπαρ: Naos (Διεθνής κουζίνα), Market Grill (Barbeque), Vento (Μεσογειακή κουζίνα), Bana (γεύσεις Καραϊβικής, ασιατική και κινέζικη κουζίνα), Fuego (Κουβανέζικη κουζίνα), Passion (Signature dishes), Royal Restaurant (πρωινό, μεσημεριανό και βραδινό γεύμα ‘A la carte), The Reserve Restaurant (Διεθνής κουζίνα - Μπουφέ), Sunset Grill (Barbeque), Family Grill - Trattoria “Olio” (Barbeque, snacks), Cub amigos Kids Corner (Kids Club): (Μπουφέ για παιδιά με snacks), Lobby Bar Kristal (ποτά, snaks και ροφήματα), Lobby Bar La Notte (Royal Service) (ποτά, snacks και ροφήματα), Lobby Bar Lunas (Reserve & Royal Services) (ποτά, snacks και ροφήματα), Avenue Bar (ποτά και cocktail με θέα το ηλιοβασίλεμα), Daiquiri (κουβανέζικα και διεθνή ποτά), Piano Bar (κρασί και ποτά), Smoothies Bar (χυμοί από φυσικά φρούτα και smoothies), Red Lounge (Pub με διεθνή cocktail και ποτά), Gaby Beach (cocktail και snacks), Sunset Bar (ποτά και cocktail), Sunrise Bar (Royal Services by the Pool) (ποτά και cocktail), The Reserve Bar (Royal & Reserve Services by the Pool) (ποτά και cocktail), El Chiringuito (snacks και cocktail)",
