      "Εστιατόρια / Μπαρ: Restaurant Telegrafo: Κουβανέζικη κουζίνα, μπουφέ με πρωινό και βραδινό γεύμα, ποτά & cocktails, ζωντανή μουσική).",
      "Διεύθυνση: 416 Paseo de Martí, La Habana 10600, Cuba",
