    "seoDescEn": "",
    "bodyEl": [
      "Είσαι έτοιμος για το ταξίδι της ζωής σου στην Κούβα, αλλά απεχθάνεσαι τη γραφειοκρατία;",
      "Λέμε να κάνουμε την προετοιμασία σου απλή όπως ένα Κουβανέζικο mojito! 🍹",
      "Κατέβασε δωρεάν τον πλήρη οδηγό για τα απαραίτητα ταξιδιωτικά έγγραφα που χρειάζεσαι για την Κούβα!",
      "Εξοικονόμησε Χρόνο: Όλες οι απαραίτητες πληροφορίες συγκεντρωμένες σε ένα χρήσιμο έγγραφο.",
      "Γλίτωσε Ταλαιπωρία: Μάθε ποια έγγραφα χρειάζεσαι και πώς να τα εκδώσεις, για να αποφύγεις κάθε δυσάρεστη εκπλήξεις.",
      "Βήμα-προς-Βήμα Διαδικασία: Ακολούθησε απλές οδηγίες με τη σωστή σειρά, για να ολοκληρώσεις γρήγορα και εύκολα την προετοιμασία σου.",
      "BONUS 🎁: Απόκτησε πρόσβαση σε ένα χρήσιμο βίντεο με αναλυτικές οδηγίες για τη συμπλήρωση της φόρμας D Viajeros, ώστε να ταξιδέψεις χωρίς άγχος!",
      "Ο Πλήρης Οδηγός για τα Απαραίτητα Ταξιδιωτικά Έγγραφα Κατέβασε τον οδηγό τώρα και κάνε το πρώτο βήμα για το ταξίδι της ζωής σου! 🌟 First Name Email* >> ΕΙΝΑΙ ΓΙΑ ΕΜΕΝΑ! >> Marketing by ActiveCampaign",
      "facebook",
      "instagram",
      "pinterest",
      "twitter",
      "linkedin"
    ],
