    "bodyEl": [
      "Αβάνα - Βινιάλες - Γουαμά - Σιενφουέγος - Τρινιδάδ - Κάγιο Σάντα Μαρία - Αβάνα",
      "Το πρόγραμμα προσφέρεται καθημερινά όλο το χρόνο | Οδικές μεταφορές: με ιδιωτικό όχημα (ταξί ή mini van) | Διαμονή: σε Boutique Casas Particulares στην Αβάνα & στο Τρινιδάδ, ξενοδοχείο 4* στο Κάγιο Σάντα Μαρία και ξενοδοχείο 5* την τελευταία διανυκτέρευση στην Αβάνα | Έλληνας Ξεναγός στην Αβάνα",
      "Ταξίδι στην Κούβα με Έλληνα ξεναγό στην Αβάνα & τοπικό οδηγό: τι θα δείτε! | Αβάνα - Σιενφουέγος - Τρινιδάδ - Κάγιο Σάντα Μαρία - Αβάνα:",
      "Πρόγραμμα | Ταξίδι στην Κούβα με Έλληνα ξεναγό στην Αβάνα & τοπικό οδηγό | Αβάνα - Σιενφουέγος - Τρινιδάδ - Κάγιο Σάντα Μαρία - Αβάνα",
      "Άφιξη στην Αβάνα. Στο αεροδρόμιο της Αβάνας θα σας υποδεχτεί ο τοπικός οδηγός σας. Μεταφορά στο ξενοδοχείο/Casa Particular και τακτοποίηση. Βράδυ ελεύθερο Διανυκτέρευση στην Αβάνα.",
      "Η πρώτη μέρα στην Αβάνα ξεκινά με ξενάγηση στα σημαντικότερα αξιοθέατα της πόλης. Εκτός του ιστορικού κέντρου η ξενάγηση πραγματοποιείται με το ιδιωτικό όχημα με στάσεις για φωτογραφίες. Θα δείτε την πλατεία της Επανάστασης (Plaza de la Revolucion) όπου θα θαυμάσετε το μαρμάρινο πύργο σε σχήμα αστεριού ύψους 109 μέτρων και το άγαλμα του εθνικού ήρωα της Κούβας, Χοσέ Μαρτί και τα σημαντικά κυβερνητικά και δημόσια κτήρια που πλαισιώνουν την πλατεία: την Εθνική Βιβλιοθήκη, το Υπουργείο Εσωτερικών, το Υπουργείο Επικοινωνιών και το Εθνικό Θέατρο.",
      "Μετάβαση στο ιστορικό κέντρο της Αβάνας (Havana Vieja) και περιήγηση με τα πόδια στις 4 πλατείες: πλατεία του Καθεδρικού Ναού (Plaza de la Catedral), πλατεία των Όπλων (Plaza de Armas), πλατεία του Αγίου Φραγκίσκου (Plaza de San Fransisco) όπου βρίσκεται και ο ορθόδοξος ναός του Αγίου Νικολάου.",
      "Επιστροφή στο κατάλυμα και υπόλοιπη μέρα ελεύθερη. Διανυκτέρευση στην Αβάνα.",
      "Highlights: Casa del Veguero, Σπηλιά του Ινδιάνου, Βραχογραφία της Προϊστορίας",
      "Αναχώρηση νωρίς το πρωί για την εκδρομή στην επαρχία Πινάρ Ντελ Ρίο Δραστηριότητες:",
      "Μεταφορά στην κοιλάδα Βινιάλες, και περιήγηση στην περιοχή με τα πόδια",
      "Επίσκεψη σε αγροτόσπιτο (Casa del Veguero) όπου καλλιεργείται ο καλύτερος καπνός για τα παγκοσμίως διάσημα πούρα Habanos",
      "Επίσκεψη στη Σπηλιά του Ινδιάνου: το μεγαλύτερο μέρος της επίσκεψης διεξάγεται με τα πόδια και στο τέλος μία μικρή πλεύση με βάρκες (περιλαμβάνεται είσοδος)",
      "Επίσκεψη στην βραχογραφία Mural de la Prehistoria (περιλαμβάνεται είσοδος)",
      "Απολαύστε το γεύμα σας σε τοπικό εστιατόριο (περιλαμβάνεται)",
      "Επιστροφή στο κατάλυμα αργά το απόγευμα",
      "Διανυκτέρευση στην Αβάνα.",
      "Ελεύθερη μέρα στην Αβάνα για να την αξιοποιήσετε όπως επιθυμείτε Διανυκτέρευση στην Αβάνα.",
      "Αναχώρηση από την Αβάνα για την πόλη Τρινιδάδ. Στη διαδρομή θα δείτε στην περιοχή Γουαμά το εκτροφείο κροκόδειλων και την αναπαράσταση Ινδιάνικους χωριού των Ταϊνος (μετάβαση με ταχύπλοα μέσα από τα κανάλια και τη λίμνη του Θησαυρού). Συνέχεια για το Σιενφουέγος, την μοναδική πόλη της Κούβας που ιδρύθηκε από Γάλλους. Η πόλη του τραγουδιστή Benny More είναι μία όμορφη πόλη που αποκαλείται από τους ντόπιους «Μαργαριτάρι του Νότου». Θα την εξερευνήσουμε με βόλτα στην πλατεία Χοσέ Μαρτί. Συνέχεια στην Μαλεκόν του Σιενφουέγος έως το Palacio del Valle όπου θα απολαύσετε ένα κοκτέιλ στην ταράτσα με θέα την Καραϊβική. Μετάβαση στο Yacht Club της πόλης για το γεύμα. Συνέχεια της διαδρομής για το Τρινιδάδ Διανυκτέρευση στο Τρινιδάδ.",
      "Πρόγευμα στο κατάλυμα και αναχώρηση για το βουνό Topes de Collantes. Μετάβαση με φορτηγά στο Πάρκο Guanayara και περπάτημα στο μονοπάτι Centinelas del Río Melodioso Γεύμα σε τοπικ"
    ],
