    "bodyEl": [
      "Με μια ματιά το ατομικό ταξίδι Explora Cuba",
      "Αβάνα (3) - Τρινιδάδ (2) - Βαραδέρο (2):",
      "Αναχωρήσεις: καθημερινές | Οδικές μεταφορές: ιδιωτικές",
      "Διαμονή: Casas Particulares & ξενοδοχεία 3*",
      "*Δεν περιλαμβάνεται αεροπορικό εισιτήριο μετάβασης στην Κούβα",
      "Τι δεν πρέπει να χάσω | Ατομικό ταξίδι Explora Cuba (Αβάνα - Τρινιδάδ - Βαραδέρο):",
      "Πρόγραμμα | Ατομικά ταξίδι Explora Cuba (Αβάνα - Τρινιδάδ - Βαραδέρο)",
      "Άφιξη στην Αβάνα. Υποδοχή στο αεροδρόμιο από τοπικό συνεργάτη και μεταφορά στο ξενοδοχείο/casa particular.",
      "Περιπατητική ξενάγηση στο ιστορικό κέντρο της Αβάνας. Επίσκεψη στην Πλατεία των Όπλων (Plaza de Armas), στην Πλατεία του Αγίου Φραγκίσκου της Ασίζης (Plaza de San Francisco de Asís), την Παλιά Πλατεία (Plaza Vieja) και την Πλατεία του Καθεδρικού Ναού (Plaza de la Catedral) μέσα από τα γραφικά δρομάκια του ιστορικού κέντρου (Obispo, Mercaderes, Oficios). Στο τέλος της ξενάγησης θα απολαύσουμε έναν κουβανέζικο καφέ ή δροσιστικό coctail σε τοπικό μπαρ. Η ξενάγηση ολοκληρώνεται στο ιστορικό κέντρο.",
      "Ημερήσια εκδρομή Σορόα / Βινιάλες με γεύμα σε τοπικό εστιατόριο (Full Day: 08.00 – 17.00). Επίσκεψη στον κήπο με τις ορχιδέες στην περιοχή Σορόα και προαιρετικά στον καταρράκτη ύψους 20 μέτρων. Στάση στο «μπαλκόνι της κοιλάδας» Βινιάλες για πανοραμική φωτογραφία. Επίσκεψη στο σπήλαιο του Ινδού και στη Βραχογραφία της Προϊστορίας. Γεύμα σε τοπικό εστιατόριο (περιλαμβάνεται αναψυκτικό ή μπύρα ή νερό). Επιστροφή στο ξενοδοχείο/casa particular το απόγευμα.",
      "Αναχώρηση από την Αβάνα μέσω της πόλης Σιενφουέγος (πανοραμική ξενάγηση) με τελικό προορισμό το Τρινιδάδ. Καθ'οδόν προαιρετική επίσκεψη στην περιοχή Γουαμά (εκτροφείο κροκοδείλων και ινδιάνικο χωριό).",
      "Ελεύθερη μέρα στο Τρινιδάδ",
      "Αναχώρηση για το Βαραδέρο μέσω Σάντα Κλάρα (ελεύθερος χρόνος για επίσκεψη στο Μουσείο και το Μαυσωλείο του Τσε Γκεβάρα – χωρίς ξεναγό). Άφιξη στο ξενοδοχείο στο Βαραδέρο αργά το απόγευμα.",
      "Ελεύθερη μέρα για να απολαύσετε τη διαμονή σας στο Βαραδέρο",
      "Το μεσημέρι μεταφορά από το ξενοδοχείο για το αεροδρόμιο της Αβάνας.",
      "Διαμονή: τρεις (03) διανυκτερεύσεις στην Αβάνα σε Boutique Historic Casa Particular στο ιστορικό κέντρο της Αβάνας, δύο (02) διανυκτερεύσεις στο Τρινιδάδ σε Boutique Historic Casa Particular στο ιστορικό κέντρο του Τρινιδάδ, δύο (02) διανυκτερεύσεις στο Βαραδέρο στο ξενοδοχείο Melia Internacional 5* σε Premium THE LEVEL Room.",
      "Ιδιωτικές οδικές μεταφορές από αεροδρόμιο Αβάνας - κατάλυμμα Αβάνας, κατάλυμμα Αβάνας - κατάλυμμα Τρινιδάδ, κατάλυμμα Τρινιδάδ - ξενοδοχείο Βαραδέρο, ξενοδοχείο Βαραδέρο - αεροδρόμιο Αβάνας (σε περίπτωση πρωινής αναχώρησης η τελευταία διανυκτέρευση πραγματοποιείται στην Αβάνα)",
      "Walking Tour στο ιστορικό κέντρο της Αβάνας, ημερήσια εκδρομή στην Κοιλάδα Βινιάλες",
      "Τουριστική βίζα για την είσοδο στην Κούβα",
      "Ταξιδιωτική ασφάλεια - περιλαμβάνει ιατροφαρμακευτικές καλύψεις υποχρεωτικές για την είσοδο στην Κούβα",
      "Χάρτης – ενημερωτικό υλικό",
      "Η τιμή δεν περιλαμβάνει το αεροπορικό εισιτήριο μετάβασης στην Κούβα. Τις ημερομηνίες υψηλής εποχικότητας Χριστουγέννων, Πρωτοχρονιά, Πάσχα θα υπάρξει επιβάρυνση τιμής",
      "Παρέα ή οικογένεια 6 - 8 ατόμων:",
      "1/11/2023 - 30/10/2024:",
      "1190 Ευρώ ανά άτομο σε δίκλινο δωμάτιο",
      "επιβάρυνση μονοκλίνου: 400 Ευρώ",
      "Έλληνας ξεναγός έως το Βαραδέρο: επιβάρυνση 130 Ευρώ κατ’ άτομο",
      "Παρέα ή οικογένεια 4 ατόμων:",
      "1/11/2023 - 30/10/2024:",
      "1240 Ευρώ ανά άτομο σε δίκλινο δωμάτιο,",
      "επιβάρυνση μονοκλίνου: 400 Ευρώ",
      "Έλληνας ξεναγός έως το Βαραδέρο: επιβάρυνση 150 Ευρώ κατ’ άτομο",
      "Συμμετοχή 2 ατόμων:",
      "1/11/2023 - 30/10/2024:"
    ],
