      "Πρόγραμμα | Ταξίδι στην Κούβα με τοπικό αγγλόφωνο ξεναγό | Αβάνα - Βινιάλες - Σάντα Κλάρα - Σιενφουέγος - Τρινιδάδ - Topes de Collantes - Βαραδέρο",
      "Άφιξη στην Αβάνα. Υποδοχή στο αεροδρόμιο από τοπικό συνεργάτη και μεταφορά στο ξενοδοχείο σας.",
      "Διανυκτέρευση στην Αβάνα",
      "Πρόγευμα στο ξενοδοχείο.",
      "Ξενάγηση στην Αβάνα: πανοραμική ξενάγηση στα σύγχρονα προάστεια της Αβάνας Βεδάδο και Μιραμάρ με το πούλμαν και επιστροφή στο ιστορικό κέντρο για την περιήγηση με τα πόδια (Walking Tour)..",
      "Σημαντικά αξιοθέατα κατά τη διάρκεια της περιήγησης: Πλατεία της Επανάστασης, Πανεπιστήμιο της Αβάνας, Μουσείο της Επανάστασης, Καπιτώλιο, Πλατεία του Καθεδρικού Ναού, Πλατεία του Αγίου Φραγκίσκου της Ασίζης, Ελληνική Ορθόδοξη Εκκλησία Αγίου Νικολάου, Πλατεία των Όπλων, Φρούριο RealFuerza, Ναϊσκος El Templete, Παλιά Πλατεία.",
      "Γεύμα σε τοπικό εστιατόριο.",
      "Διανυκτέρευση στην Αβάνα.",
      "Highlights: Casa del Veguero, Σπηλιά του Ινδιάνου, Βραχογραφία της Προϊστορίας",
