      "Δραστηριότητες:",
      "Μεταφορά στην κοιλάδα Βινιάλες, και περιήγηση στην περιοχή με τα πόδια",
      "Επίσκεψη σε αγροτόσπιτο (Casa del Veguero) όπου καλλιεργείται ο καλύτερος καπνός για τα παγκοσμίως διάσημα πούρα Habanos",
      "Επίσκεψη στη Σπηλιά του Ινδιάνου: το μεγαλύτερο μέρος της επίσκεψης διεξάγεται με τα πόδια και στο τέλος μία μικρή πλεύση με βάρκες (περιλαμβάνεται είσοδος)",
      "Επίσκεψη στην βραχογραφία Mural de la Prehistoria (περιλαμβάνεται είσοδος)",
      "Απολαύστε το γεύμα σας σε τοπικό εστιατόριο (περιλαμβάνεται)",
      "Επιστροφή στο ξενοδοχείο αργά το απόγευμα",
      "Διανυκτέρευση στην Αβάνα.",
      "Αναχώρηση για την πόλη Τρινιδάδ, μέσω των πόλεων Σάντα Κλάρα και Σιενφουέγος.",
      "Στη Σάντα Κλάρα επίσκεψη στο Μουσείο και το Μαυσωλείο του Τσε Γκεβάρα. Συνέχεια για το Σιενφουέγος, την μοναδική πόλη της Κούβας που ιδρύθηκε από Γάλλους το 1819. Η πόλη του τραγουδιστή Benny More είναι μία πόλη ιδιαίτερης ομορφιάς που αποκαλείται από τους ντόπιους το «Μαργαριτάρι του Νότου». Θα την εξερευνήσετε με βόλτα στην κεντρική πλατεία όπου βρίσκονται τα σημαντικότερα δημόσια κτήρια ανάμεσα στα οποία και το θέατρο Τομάς Τέρρυ, χαρακτηριστικό δείγμα του εκλεκτικισμού, που χρονολογείται από το 1889. Το θέατρο έχει φιλοξενήσει στη σκηνή του σημαντικούς καλλιτέχνες όπως την Anna Pavlova, την AliciaAlonso και τον Enrico Caruso. Η διαδρομή συνεχίζεται με το λεωφορείο στην Μαλεκόν του Σιενφουέγος (τον παραλιακό δρόμο) μέχρι την Punta Gorda όπου βρίσκεται το Palacio del Valle το αρχιτεκτονικό κόσμημα που «βλέπει» την Καραϊβική θάλασσα (περιλαμβάνεται επίσκεψη).",
      "Μεταφορά στο βουνό Topes de Collantes και τακτοποίηση στο ξενοδοχείο Los Helechos 3*",
