      "Μεταφορά με ειδικά διαμορφωμένα οχήματα στο βουνό Topes de Collantes. Εξερεύνηση της χλωρίδας και της πανίδας της περιοχής με περπάτημα σε ένα από τα μονοπάτια που καταλήγουν σε πισίνες γλυκού νερού. Ελεύθερος χρόνος για μπάνιο.",
