      "Ξενάγηση με τα πόδια στο ιστορικό κέντρο της πόλης (Αβάνα Βιέχα), μνημείο Παγκόσμιας Πολιτιστικής Κληρονομιάς. Επίσκεψη στις 4 πλατείες του ιστορικού κέντρου (πλατεία των Όπλων, πλατεία του Καθεδρικού Ναού, Πλατεία του Αγίου Φραγκίσκου της Ασίζης, Παλιά Πλατεία) – Walking Tour",
