      "Διανυκτέρευση στην Αβάνα",
      "Πρόγευμα στο Casa Particular και αναχώρηση για την πόλη Τρινιδάδ, μέσω της χερσονήσου Zapata που βρίσκεται στο νότιο τμήμα της επαρχίας Ματάνσας.",
      "Η περιοχή είναι υδροβιότοπος διεθνούς σημασίας, προστατευόμενος από τη Συνθήκη Ραμσάρ (1971), που φιλοξενεί 900 αυτόχθονα είδη χλωρίδας και ενδημικά είδη πανίδας (κουβανέζικο σπουργίτι, αμφίβια πτηνά). Ο υδροβιότοπος είναι ένας από τους καλύτερα συντηρημένους στην Καραϊβική και ενδιάμεσος σταθμός 65 πουλιών που μεταναστεύουν στη Νότια Αμερική.",
      "Προαιρετική επίσκεψη στο μεγαλύτερο κέντρο αναπαραγωγής κροκόδειλων στην Κούβα. Περιπλάνηση με ταχύπλοο* στα κανάλια και διάσχιση της λίμνης του θησαυρού. Επίσκεψη στην αναπαράσταση του πασσαλόπηκτου οικισμού των ινδιάνων Ταϊνος (ίχνη κατοίκησης των οποίων βρέθηκαν από τους αρχαιολόγους στην περιοχή). Γνωριμία με τον καθημερινό τρόπο ζωής τους.",
      "Άφιξη στο Σιενφουέγος, την μοναδική πόλη της Κούβας που ιδρύθηκε από Γάλλους το 1819. Η πόλη του τραγουδιστή Benny More είναι μία πόλη ιδιαίτερης ομορφιάς που αποκαλείται από τους ντόπιους το «Μαργαριτάρι του Νότου». Θα την εξερευνήσετε με βόλτα στην κεντρική πλατεία όπου βρίσκονται τα σημαντικότερα δημόσια κτήρια ανάμεσα στα οποία και το θέατρο Τομάς Τέρρυ, χαρακτηριστικό δείγμα του εκλεκτικισμού, που χρονολογείται από το 1889. Το θέατρο έχει φιλοξενήσει στη σκηνή του σημαντικούς καλλιτέχνες όπως την Anna Pavlova, την Alicia Alonso και τον Enrico Caruso. Η διαδρομή συνεχίζεται με το λεωφορείο στην Μαλεκόν του Σιενφουέγος (τον παραλιακό δρόμο) μέχρι την Punta Gorda όπου βρίσκεται το Palacio del Valle, το αρχιτεκτονικό κόσμημα που «βλέπει» την Καραϊβική θάλασσα.",
