      "Διανυκτέρευση στο Βουνό Topes de Collantes.",
      "Πρόγευμα στο ξενοδοχείο.",
      "Μεταφορά με φορτηγά στο Εθνικό Πάρκο Guanayara για να απολαύσετε τη φυσική ομορφιά της τροπικής βλάστησης.",
      "Παραδοσιακό γεύμα στο Casa De La Gallega",
      "Επιστροφή στο ξενοδοχείο και δείπνο.",
      "Διανυκτέρευση στο Βουνό.",
      "Πρόγευμα και αναχώρηση για τη Σάντα Κλάρα.",
      "Επίσκεψη στο Μουσείο και το Μαυσωλείο του Τσε Γκεβάρα και πανοραμική ξενάγηση της πόλης.",
      "Γεύμα σε τοπικό εστιατόριο",
      "Αναχώρηση για το Κάγιο Σάντα Μαρία μέσω της πόλης Ρεμέδιος. Στάση για φωτογραφίες και για αγορά αναμνηστικών",
      "Άφιξη στο Κάγιο Σάντα Μαρία και τακτοποίηση στο ξενοδοχείο της επιλογής σας",
      "Διανυκτέρευση στο Κάγιο Σάντα Μαρία (δεν περιλαμβάνεται στην τιμή).",
      "Ξενοδοχείο Memories Miramar"
