    "seoTitleEl": "Unesco Heritage Cities",
    "seoTitleEn": "UNESCO Heritage Cities",
    "seoDescEl": "",
    "seoDescEn": "",
    "bodyEl": [
      "9 ημέρες / 7 διανυκτερεύσεις",
      "UNESCO Heritage Cities",
      "Αναχωρήσεις: 24 Ιουνίου, 1 Ιουλίου, 5 Αυγούστου | Οδικές μεταφορές: ιδιωτικές | Διαμονή: σε Boutique Historic Casa Particular στo ιστορικό κέντρο της Αβάνας & του Τρινιδάδ",
      "Τι δεν πρέπει να χάσω | Ομαδικό Ταξίδι UNESCO Heritage Cities:",
      "Πρόγραμμα | Ομαδικό Ταξίδι UNESCO Heritage Cities:",
      "Άφιξη στην Αβάνα. Υποδοχή στο αεροδρόμιο από τοπικό συνεργάτη και μεταφορά στο ξενοδοχείο/casa particular.",
      "Περιπατητική ξενάγηση στο ιστορικό κέντρο της Αβάνας. Επίσκεψη στην Πλατεία των Όπλων (Plaza de Armas), στην Πλατεία του Αγίου Φραγκίσκου της Ασίζης (Plaza de San Francisco de Asís), την Παλιά Πλατεία (Plaza Vieja) και την Πλατεία του Καθεδρικού Ναού (Plaza de la Catedral) μέσα από τα γραφικά δρομάκια του ιστορικού κέντρου (Obispo, Mercaderes, Oficios). Στο τέλος της ξενάγησης θα απολαύσουμε έναν κουβανέζικο καφέ ή δροσιστικό coctail σε τοπικό μπαρ. Η ξενάγηση ολοκληρώνεται στο ιστορικό κέντρο.",
      "Δραστηριότητες:",
      "Επίσκεψη σε αγροτόσπιτο (Casa del Veguero) όπου καλλιεργείται ο καλύτερος καπνός για τα παγκοσμίως διάσημα πούρα Habanos",
      "Μεταφορά στην κοιλάδα Vinales, στάση στο παρατηρητήριο (Mirador de los Jasmines) για να θαυμάσετε την κοιλάδα. Είναι το ιδανικό σημείο για τις αναμνηστικές σας φωτογραφίες!",
      "Επίσκεψη στη Σπηλιά του Ινδιάνου (το μεγαλύτερο μέρος της επίσκεψης διεξάγεται με τα πόδια και στο τέλος ένα μικρό τμήμα με βάρκες)",
      "Γεύμα σε τοπικό εστιατόριο",
      "Επίσκεψη στην βραχογραφία Mural de la Prehistoria",
      "Επιστροφή στο ξενοδοχείο αργά το απόγευμα",
      "Διανυκτέρευση στην Αβάνα",
      "Πρόγευμα στο Casa Particular και αναχώρηση για την πόλη Τρινιδάδ, μέσω της χερσονήσου Zapata που βρίσκεται στο νότιο τμήμα της επαρχίας Ματάνσας.",
      "Η περιοχή είναι υδροβιότοπος διεθνούς σημασίας, προστατευόμενος από τη Συνθήκη Ραμσάρ (1971), που φιλοξενεί 900 αυτόχθονα είδη χλωρίδας και ενδημικά είδη πανίδας (κουβανέζικο σπουργίτι, αμφίβια πτηνά). Ο υδροβιότοπος είναι ένας από τους καλύτερα συντηρημένους στην Καραϊβική και ενδιάμεσος σταθμός 65 πουλιών που μεταναστεύουν στη Νότια Αμερική. Προαιρετική επίσκεψη στο μεγαλύτερο κέντρο αναπαραγωγής κροκόδειλων στην Κούβα.",
      "Προαιρετική περιπλάνηση με ταχύπλοο* στα κανάλια και διάσχιση της λίμνης του θησαυρού. Επίσκεψη στην αναπαράσταση του πασσαλόπηκτου οικισμού των ινδιάνων Ταϊνος (ίχνη κατοίκησης των οποίων βρέθηκαν από τους αρχαιολόγους στην περιοχή). Γνωριμία με τον καθημερινό τρόπο ζωής τους.",
      "Άφιξη στο Σιενφουέγος, την μοναδική πόλη της Κούβας που ιδρύθηκε από Γάλλους το 1819. Η πόλη του τραγουδιστή Benny More είναι μία πόλη ιδιαίτερης ομορφιάς που αποκαλείται από τους ντόπιους το «Μαργαριτάρι του Νότου». Θα την εξερευνήσετε με βόλτα στην κεντρική πλατεία όπου βρίσκονται τα σημαντικότερα δημόσια κτήρια ανάμεσα στα οποία και το θέατρο Τομάς Τέρρυ, χαρακτηριστικό δείγμα του εκλεκτικισμού, που χρονολογείται από το 1889. Το θέατρο έχει φιλοξενήσει στη σκηνή του σημαντικούς καλλιτέχνες όπως την Anna Pavlova, την Alicia Alonso και τον Enrico Caruso. Η διαδρομή συνεχίζεται με το λεωφορείο στην Μαλεκόν του Σιενφουέγος (τον παραλιακό δρόμο) μέχρι την Punta Gorda όπου βρίσκεται το Palacio del Valle, το αρχιτεκτονικό κόσμημα που «βλέπει» την Καραϊβική θάλασσα.",
      "Συνέχεια της διαδρομής για Τρινιδάδ.",
      "Διανυκτέρευση στο Τρινιδάδ.",
      "Ελεύθερες μέρες στην πόλη του Τρινιδάδ, μία από τις πρώτες πόλεις που ιδρύθηκαν από τους Ισπανούς στην Κούβα, γνωστή και ως πόλη Μουσείο που έχει «παγώσει» στο χρόνο… Σας προτείνουμε επίσκεψη στο Μουσείο του Ρομαντισμού (Museo Romantico) ή το Μουσείο της Πόλης (Palacio Canter"
    ],
