      "Παρακαλούμε διαβάστε προσεκτικά τους παρακάτω Όρους Συμμετοχής που διέπουν τα Ατομικά και Οργανωμένα ταξίδια της εταιρείας μας.",
      "Η σύμβαση του ταξιδιού σας πραγματοποιείται με την εταιρία ΣΚΑΪΝΤΡΗΜ ΜΟΝΟΠΡΟΣΩΠΗ Ε.Π.Ε, που φέρει το διακριτικό τίτλο GO CUBA, και που δεσμεύεται να σας προσφέρει τις διάφορες υπηρεσίες που αποτελούν μέρος του ταξιδιού σας, και εσάς, του Πελάτη (εφεξής ο Ταξιδιώτης).",
