      "Είμαστε τόσο ενθουσιασμένοι που είστε εδώ και διαβάζετε αυτό το άρθρο! Θέλουμε να σας πούμε κάτι που θα κάνει το γαμήλιο ταξίδι σας στην Αβάνα αξέχαστο!",
      "Αν επιλέξετε να ζήσετε αυτήν την απίστευτη περιπέτεια μαζί μας, θα σας"
