      "activitiesEn": [],
      "highlightsEl": "➺ Παραλαβή από το Ξενοδοχείο: Επιβιβαστείτε σε ένα κλιματιζόμενο πούλμαν που θα σας παραλάβει από το ξενοδοχείο σας σε συγκεκριμένη ώρα. Μην ανησυχείτε για τις λεπτομέρειες, τις έχουμε φροντίσει!\n \n➺ Πανοραμική Ξενάγηση με Πούλμαν: Θα Εξερευνήσετε τα σύγχρονα προάστεια της Αβάνας με άνεση από τη θέση σας. [απολαμβάνοντας το αστικό τοπίο.]\n \n➺ Περιπατητική Ξενάγηση (Walking Tour): στο ιστορικό κέντρο της Αβάνας. Με κάθε σας βήμα, θα γνωρίσετε τον πυρήνα της Αβάνας και τις πτυχές του ιστορικού κέντρου της πόλης. Θα ανακαλύψετε αρχιτεκτονικά αριστουργήματα, όμορφες γωνιές για στιγμές χαλάρωσης, καθώς και εξαίσιες εκδηλώσεις τέχνης στους δρόμους, που μετατρέπουν την πόλη σε ένα ζωντανό καμβά!\n \n➺ Must-See Τοποθεσίες: Θα δείτε την Πλατεία της Επανάστασης (Plaza de la Revolucion), το Πανεπιστήμιο της Αβάνας (Universidad de la Habana). το Προεδρικό Παλάτι (Palacio Presidencial), το Κεντρικό Πάρκο (Parque Central), το Καπιτώλιο (Capitolio Nacional), τις Πλατείες της Παλιάς Πόλης (Plaza de Armas, Plaza de la Catedral, Plaza Vieja) και φυσικά, τα εμβληματικά μπαρ-εστιατόρια Floridita και La Bodeguita del Medio (must Instagrammable spots!)\n \n➺ Φωτογραφικές Στάσεις: Κάθε φωτογραφική στάση είναι μια ευκαιρία να \"αιχμαλωτίσετε\" τη μαγεία της Αβάνας, να αποθανατίσετε μοναδικές στιγμές και να δημιουργήσετε αναμνήσεις που θα σας συντροφεύουν για πάντα.\n\nΗ πλήρης εμπειρία της Αβάνας! Από τις πιο φωτογενείς γωνίες της πόλης μέχρι τα απόκρυφα μυστικά της, είμαστε εδώ για να κάνουμε αυτό το ταξίδι αξέχαστο. Είστε έτοιμοι;",
      "highlightsEn": "➺ Παραλαβή από το Ξενοδοχείο: Επιβιβαστείτε σε ένα κλιματιζόμενο πούλμαν που θα σας παραλάβει από το ξενοδοχείο σας σε συγκεκριμένη ώρα. Μην ανησυχείτε για τις λεπτομέρειες, τις έχουμε φροντίσει!\n \n➺ Πανοραμική Ξενάγηση με Πούλμαν: Θα Εξερευνήσετε τα σύγχρονα προάστεια της Αβάνας με άνεση από τη θέση σας. [απολαμβάνοντας το αστικό τοπίο.]\n \n➺ Περιπατητική Ξενάγηση (Walking Tour): στο ιστορικό κέντρο της Αβάνας. Με κάθε σας βήμα, θα γνωρίσετε τον πυρήνα της Αβάνας και τις πτυχές του ιστορικού κέντρου της πόλης. Θα ανακαλύψετε αρχιτεκτονικά αριστουργήματα, όμορφες γωνιές για στιγμές χαλάρωσης, καθώς και εξαίσιες εκδηλώσεις τέχνης στους δρόμους, που μετατρέπουν την πόλη σε ένα ζωντανό καμβά!\n \n➺ Must-See Τοποθεσίες: Θα δείτε την Πλατεία της Επανάστασης (Plaza de la Revolucion), το Πανεπιστήμιο της Αβάνας (Universidad de la Habana). το Προεδρικό Παλάτι (Palacio Presidencial), το Κεντρικό Πάρκο (Parque Central), το Καπιτώλιο (Capitolio Nacional), τις Πλατείες της Παλιάς Πόλης (Plaza de Armas, Plaza de la Catedral, Plaza Vieja) και φυσικά, τα εμβληματικά μπαρ-εστιατόρια Floridita και La Bodeguita del Medio (must Instagrammable spots!)\n \n➺ Φωτογραφικές Στάσεις: Κάθε φωτογραφική στάση είναι μια ευκαιρία να \"αιχμαλωτίσετε\" τη μαγεία της Αβάνας, να αποθανατίσετε μοναδικές στιγμές και να δημιουργήσετε αναμνήσεις που θα σας συντροφεύουν για πάντα.\n\nΗ πλήρης εμπειρία της Αβάνας! Από τις πιο φωτογενείς γωνίες της πόλης μέχρι τα απόκρυφα μυστικά της, είμαστε εδώ για να κάνουμε αυτό το ταξίδι αξέχαστο. Είστε έτοιμοι;"
