      "highlightsEl": "Επίσκεψη εξωτερικά του φρουρίου Morro για μία αναμνηστική φωτογραφία με πανοραμική θέα της Αβάνας\nΕπίσκεψη στο πάρκο Zapata στην περιοχή Μιραμάρ και συνέχεια στην 5η Λεωφόρο με τις εντυπωσιακές αριστοκρατικές επαύλεις των 1920 - 1950\nΣτάση στην Fusterlandia, την πιο \"μωσαϊκή\" γειτονιά της Λατινικής Αμερικής\nΠεριήγηση στην κεντρική λαχαναγορά του Δήμου Marianao και την τοπική αγορά\nΕπίσκεψη στο τροπικό δάσος με το ομώνυμο ποτάμι Almendares που τροφοδοτούσε με νερό τις ισπανικές γαλέρες στα χρόνια της Ισπανικής Κυριαρχίας\n\nΚατά την ξενάγηση θα απολαύσετε ένα δροσιστικό Mojito και τηγανητά κουβανέζικα μπανανο-τσιπς σε αυθεντική γειτονιά!\nΓλώσσες: Ελληνικά\nΚόστος ανά άτομο: \nΣυμμετοχή 2 ατόμων: 120 Ευρώ\nΣυμμετοχή 3 ατόμων: 110 Ευρώ\nΣχόλια:\n\nΗ περιήγηση προσφέρεται καθημερινά όλο το χρόνο\nΗ περιήγηση πραγματοποιείται για ελάχιστη συμμετοχή 2 ατόμων\nH περιήγηση ξεκινάει με ιδιωτικό όχημα (μοντέρνο όχημα ή αυτοκίνητο αντίκα) από το κατάλυμα σας.\nΚρατήσεις: τουλάχιστον 1 εβδομάδα πριν την έναρξη της εκδρομής",
