      "expectEl": "Μία διήμερη εμπειρία που συνδυάζει τον πολιτισμό, την ιστορία και τη φυσική ομορφιά της Κούβας, με στάσεις σε ιστορικά αξιοθέατα, απολαυστικά γεύματα και επαφή με την αγνή φύση. Είναι ό,τι κοντινότερο σε μια πολυσυλλεκτική \"γεύση\" της Κούβας που μπορεί κανείς να ζήσει σε ένα τόσο σύντομο χρονικό διάστημα.\n \n \nΤιμή ανά Άτομο σε Δίκλινο Δωμάτιο: Ενήλικας 210 Ευρώ, Παιδί 180 Ευρώ\n \n \nΏρα αναχώρησης: 07.30\n \n \nΣημείο Αναχώρησης: από Επιλεγμένα Ξενοδοχεία\n \n \nΔιαθεσιμότητα: μόνο κάθε Τετάρτη",
