      "includedEl": "Μεταφορές με κλιματιζόμενο πούλμαν, υπηρεσία επαγγελματία αγγλόφωνου ξεναγού, μία διανυκτερεύση στο ξενοδοχείο Los Helechos 3*, διατροφή: ένα πρωινό, 2 γεύματα & 1 δείπνο, αξιοθέατα: Σάντα Κλάρα (Μουσείο & Μαυσωλείο Τσε Γκεβάρα), Σιενφουέγος (Πανοραμική Περιήγηση με στάση στην Κεντρική Πλατεία), Τρινιδάδ (walking tour, επίσκεψη σε μουσείο, ποτό στο μπαρ La Canchanchara), πεζοπορία στο βουνό Topes de Collantes στο μονοπάτι Centinelas del río melodioso - μπάνιο σε φυσική λίμνη με καταρράκτη (δεν περιλαμβάνονται φιλοδωρήματα)",
      "includedEn": "Μεταφορές με κλιματιζόμενο πούλμαν, υπηρεσία επαγγελματία αγγλόφωνου ξεναγού, μία διανυκτερεύση στο ξενοδοχείο Los Helechos 3*, διατροφή: ένα πρωινό, 2 γεύματα & 1 δείπνο, αξιοθέατα: Σάντα Κλάρα (Μουσείο & Μαυσωλείο Τσε Γκεβάρα), Σιενφουέγος (Πανοραμική Περιήγηση με στάση στην Κεντρική Πλατεία), Τρινιδάδ (walking tour, επίσκεψη σε μουσείο, ποτό στο μπαρ La Canchanchara), πεζοπορία στο βουνό Topes de Collantes στο μονοπάτι Centinelas del río melodioso - μπάνιο σε φυσική λίμνη με καταρράκτη (δεν περιλαμβάνονται φιλοδωρήματα)",
      "bringEl": "Άνετα Ρούχα, Μαγιό, Πετσέτα, Αντιηλιακή Προστασία, Φωτογραφική Μηχανή, Χρήματα για φιλοδωρήματα",
      "bringEn": "Άνετα Ρούχα, Μαγιό, Πετσέτα, Αντιηλιακή Προστασία, Φωτογραφική Μηχανή, Χρήματα για φιλοδωρήματα",
