      "activitiesEl": [],
      "activitiesEn": [],
      "highlightsEl": "➺ Πολυδιάστατη Εμπειρία Ταξιδιού\n\nΣε αυτή τη διήμερη εκδρομή, θα γνωρίσετε σε δύο διαφορετικές κουβανέζικες πόλεις - Cienfuegos & Trinidad και το βουνό Topes de Collantes. Από την αστική κομψότητα του Cienfuegos μέχρι την αποικιακή χάρη του Trinidad και την φυσική ομορφιά του Topes de Collantes, θα ζήσετε την πολυπλοκότητα και την πολυδιάστατη φύση της Κούβας σε μία μόνο περιήγηση.\n\n.\n\n \n \n➺ Πολιτιστική Εμβάθυνση\n\nΘα επισκεφθείτε μουσεία, αξιοθέατα και παραδοσιακούς χώρους όπως το μπαρ La Canchánchara. Θα αποκτήστε επίγνωση της κουβανέζικης ιστορίας και πολιτισμού με έναν αρκετά άμεσο τρόπο, με περισσότερες γνώσεις από αυτές που αποτυπώνονται σε ταξιδιωτικούς οδηγούς.\n\n \n \n➺ Επαφή με τη Φύση\n\nΘα απολαύσετε την ποικιλομορφία της φύσης περπατώντας σε μονοπάτια στο βουνό Topes de Collantes και θα κολυμπήσετε στα κρυστάλλινα νερά της φυσικής λίμνης Venado. Η διαδρομή είναι ιδανική για τους λάτρεις της φύσης που θέλουν να εξερευνήσουν την εξωτική χλωρίδα και πανίδα της περιοχής.\n\n \n\n \n➺ Οργάνωση και Άνεση\n\nΜε την παραλαβή και επιστροφή στο ξενοδοχείο σας, καθώς και τη διανυκτέρευση στο βουνό Topes de Collantes, όλες οι λεπτομέρειες έχουν ληφθεί υπόψη για να κάνουν το ταξίδι σας όσο το δυνατόν πιο άνετο και ευχάριστο.\n\n \n➺ Διατροφή\n \n\nΔεν χρειάζεται να ανησυχείτε για το φαγητό. Με πρόγευμα, γεύμα και δείπνο την πρώτη μέρα και πρόγευμα και γεύμα τη δεύτερη μέρα δε θα ψάχνετε εστιατόρια και μπαρ.\n\n \n\n \n \n\nΑυτή η εκδρομή είναι ό,τι πρέπει για όποιον θέλει να εμβαθύνει στον πολιτισμό, την ιστορία και την φυσική ομορφιά της Κούβας, χωρίς να θυσιάζει την άνεση που μπορεί να προσφέρει μια οργανωμένη περιήγηση.",
      "highlightsEn": "➺ Πολυδιάστατη Εμπειρία Ταξιδιού\n\nΣε αυτή τη διήμερη εκδρομή, θα γνωρίσετε σε δύο διαφορετικές κουβανέζικες πόλεις - Cienfuegos & Trinidad και το βουνό Topes de Collantes. Από την αστική κομψότητα του Cienfuegos μέχρι την αποικιακή χάρη του Trinidad και την φυσική ομορφιά του Topes de Collantes, θα ζήσετε την πολυπλοκότητα και την πολυδιάστατη φύση της Κούβας σε μία μόνο περιήγηση.\n\n.\n\n \n \n➺ Πολιτιστική Εμβάθυνση\n\nΘα επισκεφθείτε μουσεία, αξιοθέατα και παραδοσιακούς χώρους όπως το μπαρ La Canchánchara. Θα αποκτήστε επίγνωση της κουβανέζικης ιστορίας και πολιτισμού με έναν αρκετά άμεσο τρόπο, με περισσότερες γνώσεις από αυτές που αποτυπώνονται σε ταξιδιωτικούς οδηγούς.\n\n \n \n➺ Επαφή με τη Φύση\n\nΘα απολαύσετε την ποικιλομορφία της φύσης περπατώντας σε μονοπάτια στο βουνό Topes de Collantes και θα κολυμπήσετε στα κρυστάλλινα νερά της φυσικής λίμνης Venado. Η διαδρομή είναι ιδανική για τους λάτρεις της φύσης που θέλουν να εξερευνήσουν την εξωτική χλωρίδα και πανίδα της περιοχής.\n\n \n\n \n➺ Οργάνωση και Άνεση\n\nΜε την παραλαβή και επιστροφή στο ξενοδοχείο σας, καθώς και τη διανυκτέρευση στο βουνό Topes de Collantes, όλες οι λεπτομέρειες έχουν ληφθεί υπόψη για να κάνουν το ταξίδι σας όσο το δυνατόν πιο άνετο και ευχάριστο.\n\n \n➺ Διατροφή\n \n\nΔεν χρειάζεται να ανησυχείτε για το φαγητό. Με πρόγευμα, γεύμα και δείπνο την πρώτη μέρα και πρόγευμα και γεύμα τη δεύτερη μέρα δε θα ψάχνετε εστιατόρια και μπαρ.\n\n \n\n \n \n\nΑυτή η εκδρομή είναι ό,τι πρέπει για όποιον θέλει να εμβαθύνει στον πολιτισμό, την ιστορία και την φυσική ομορφιά της Κούβας, χωρίς να θυσιάζει την άνεση που μπορεί να προσφέρει μια οργανωμένη περιήγηση."
