      "includedEl": "Μεταφορές με κλιματιζόμενο πούλμαν, υπηρεσία επαγγελματία αγγλόφωνου ξεναγού, είσοδος σε ξενοδοχείο All Inclusive στο Βαραδέρο, γεύμα μπουφέ, ποτά & αναψυκτικά στα μπαρ του ξενοδοχείου, (δεν περιλαμβάνονται φιλοδωρήματα)",
