      "activitiesEl": [],
      "activitiesEn": [],
      "highlightsEl": "➺ Ανεπανάληπτη Φυσική Ομορφιά\n\nΑπολαύστε τη μοναδική φυσική ομορφιά της παραλίας Βαραδέρο, όπου η κατάλευκη, ατελείωτη αμμουδιά συναντά τα τιρκουάζ νερά. Είναι το ιδανικό σκηνικό για να αφεθείτε στις αγκαλιές του ήλιου και της θάλασσας.\n\n.\n\n \n \n➺ Πολυτέλεια και Άνεση\n\nΕξασφαλίζουμε την πολυτέλεια που αξίζετε, από το κλιματιζόμενο λεωφορείο που θα σας παραλάβει, μέχρι τη φιλοξενία σε ένα εκλεκτό ξενοδοχείο σε καθεστώς \"All Inclusive\".\n\n \n \n➺ Γαστρονομικές Απολαύσεις\n\nΔοκιμάστε την κουβανέζικη κουζίνα: ένα πλούσιο μπουφέ μεσημεριανού συνοδεύεται από δροσιστικά ποτά - όλα περιλαμβάνονται στην τιμή της εκδρομής.\n\n \n\n \n➺ Απεριόριστες Δραστηριότητες\nΕκμεταλλευτείτε τον ελεύθερο χρόνο σας παίζοντας παιχνίδια στην άμμο, δοκιμάζοντας μη μηχανοκίνητα ναυτικά σπορ ή απλά χαλαρώνοντας στην όμορφη παραλία.\n\n \n➺ Εύκολη και Άνετη Επιστροφή\n \n\nΣτο τέλος μιας ημέρας γεμάτης αναμνήσεις, επιστρέψτε αναζωογονημένοι και ξεκούραστοι στο ξενοδοχείο σας στην Αβάνα, έτοιμοι για την επόμενη κουβανική περιπέτεια που σας περιμένει.\n \n\n \n \nΜε τόσα πολλά να προσφέρει, αυτή η εκδρομή στο Βαραδέρο είναι πολύ περισσότερο από ένα απλό \"break\" από την πόλη - είναι μια πραγματική απόδραση που σας ταξιδέψει σε έναν κόσμο ολοκληρωτικής χαλάρωσης και πολυτέλειας. Είναι η ευκαιρία να ξεφύγετε από το αστικό τοπίο και να βυθιστείτε σε μια εμπειρία που θα σας μείνει αξέχαστη. Επιστρέψτε με τις μπαταρίες φορτισμένες και μια χούφτα αναμνήσεις που θα σας κρατούν συντροφιά μέχρι το επόμενο ταξίδι σας στην Κούβα!",
      "highlightsEn": "➺ Ανεπανάληπτη Φυσική Ομορφιά\n\nΑπολαύστε τη μοναδική φυσική ομορφιά της παραλίας Βαραδέρο, όπου η κατάλευκη, ατελείωτη αμμουδιά συναντά τα τιρκουάζ νερά. Είναι το ιδανικό σκηνικό για να αφεθείτε στις αγκαλιές του ήλιου και της θάλασσας.\n\n.\n\n \n \n➺ Πολυτέλεια και Άνεση\n\nΕξασφαλίζουμε την πολυτέλεια που αξίζετε, από το κλιματιζόμενο λεωφορείο που θα σας παραλάβει, μέχρι τη φιλοξενία σε ένα εκλεκτό ξενοδοχείο σε καθεστώς \"All Inclusive\".\n\n \n \n➺ Γαστρονομικές Απολαύσεις\n\nΔοκιμάστε την κουβανέζικη κουζίνα: ένα πλούσιο μπουφέ μεσημεριανού συνοδεύεται από δροσιστικά ποτά - όλα περιλαμβάνονται στην τιμή της εκδρομής.\n\n \n\n \n➺ Απεριόριστες Δραστηριότητες\nΕκμεταλλευτείτε τον ελεύθερο χρόνο σας παίζοντας παιχνίδια στην άμμο, δοκιμάζοντας μη μηχανοκίνητα ναυτικά σπορ ή απλά χαλαρώνοντας στην όμορφη παραλία.\n\n \n➺ Εύκολη και Άνετη Επιστροφή\n \n\nΣτο τέλος μιας ημέρας γεμάτης αναμνήσεις, επιστρέψτε αναζωογονημένοι και ξεκούραστοι στο ξενοδοχείο σας στην Αβάνα, έτοιμοι για την επόμενη κουβανική περιπέτεια που σας περιμένει.\n \n\n \n \nΜε τόσα πολλά να προσφέρει, αυτή η εκδρομή στο Βαραδέρο είναι πολύ περισσότερο από ένα απλό \"break\" από την πόλη - είναι μια πραγματική απόδραση που σας ταξιδέψει σε έναν κόσμο ολοκληρωτικής χαλάρωσης και πολυτέλειας. Είναι η ευκαιρία να ξεφύγετε από το αστικό τοπίο και να βυθιστείτε σε μια εμπειρία που θα σας μείνει αξέχαστη. Επιστρέψτε με τις μπαταρίες φορτισμένες και μια χούφτα αναμνήσεις που θα σας κρατούν συντροφιά μέχρι το επόμενο ταξίδι σας στην Κούβα!"
